-- ── identity_verifications (Identity & Access) ──
CREATE TABLE identity_verifications (
    id uuid NOT NULL DEFAULT uuidv7(),
    user_id uuid NOT NULL,
    document_type text,
    document_country char(2),
    status identity_check_status NOT NULL DEFAULT 'pending',
    ocr_succeeded boolean,
    face_match_score numeric(5,4),
    failure_reason text,
    provider text,
    created_at timestamptz NOT NULL DEFAULT now(),
    completed_at timestamptz,
    CONSTRAINT identity_verifications_pkey PRIMARY KEY (id),
    CONSTRAINT identity_verifications_chk1 CHECK (status = 'pending' OR completed_at IS NOT NULL),
    CONSTRAINT identity_verifications_chk2 CHECK (status <> 'passed' OR (ocr_succeeded AND face_match_score IS NOT NULL))
);
COMMENT ON TABLE identity_verifications IS 'Outcome of ID-document OCR + selfie face-match. Result only — images are deleted after the check.';

-- ── trust_score_events (Identity & Access) ──
CREATE TABLE trust_score_events (
    id uuid NOT NULL DEFAULT uuidv7(),
    user_id uuid NOT NULL,
    delta numeric(5,2) NOT NULL,
    score_after numeric(5,2) NOT NULL,
    reason_code text NOT NULL,
    reference_type text,
    reference_id uuid,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT trust_score_events_pkey PRIMARY KEY (id),
    CONSTRAINT trust_score_events_chk1 CHECK (score_after BETWEEN 0 AND 100)
);
COMMENT ON TABLE trust_score_events IS 'Every trust-score change with reason and resulting score (score is clamped and can be set, so the result is stored).';
COMMENT ON COLUMN trust_score_events.reason_code IS 'review_helpful, spam_report, flag_confirmed, level2_baseline…';

-- ── product_variants (Product Catalogue (Registry)) ──
CREATE TABLE product_variants (
    id uuid NOT NULL DEFAULT uuidv7(),
    product_id uuid NOT NULL,
    name text NOT NULL,
    attributes jsonb NOT NULL DEFAULT '{}',
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT product_variants_pkey PRIMARY KEY (id),
    CONSTRAINT product_variants_product_id_name_key UNIQUE (product_id, name)
);
COMMENT ON TABLE product_variants IS 'Colour / size / pack variants of one canonical product.';

-- ── qr_labels (Digital Wallet) ──
CREATE TABLE qr_labels (
    id uuid NOT NULL DEFAULT uuidv7(),
    wallet_item_id uuid NOT NULL,
    provider text NOT NULL DEFAULT 'iotsecurityprivacy',
    template_code text NOT NULL,
    status qr_label_status NOT NULL DEFAULT 'pending',
    external_label_id text,
    payload_url text,
    image_media_id uuid,
    error text,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT qr_labels_pkey PRIMARY KEY (id),
    CONSTRAINT qr_labels_chk1 CHECK (status <> 'generated' OR payload_url IS NOT NULL),
    CONSTRAINT qr_labels_chk2 CHECK (status <> 'failed' OR error IS NOT NULL)
);
COMMENT ON TABLE qr_labels IS 'QR label generated for a wallet item via iotsecurityprivacy.org template.';

-- ── product_watches (Digital Wallet) ──
CREATE TABLE product_watches (
    id uuid NOT NULL DEFAULT uuidv7(),
    user_id uuid NOT NULL,
    product_id uuid NOT NULL,
    entitlement_id uuid NOT NULL,
    expires_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT product_watches_pkey PRIMARY KEY (id),
    CONSTRAINT product_watches_user_id_product_id_key UNIQUE (user_id, product_id)
);
COMMENT ON TABLE product_watches IS 'Watch a product not in the wallet (granted by a watchlist entitlement).';

-- ── coin_earn_rules (Rewards (TelCoins)) ──
CREATE TABLE coin_earn_rules (
    code text NOT NULL,
    amount bigint NOT NULL,
    counts_toward_daily_cap boolean NOT NULL DEFAULT true,
    per_subject_limit integer,
    lifetime_limit integer,
    confirmation_delay interval NOT NULL DEFAULT '10 minutes',
    is_active boolean NOT NULL DEFAULT true,
    CONSTRAINT coin_earn_rules_pkey PRIMARY KEY (code),
    CONSTRAINT coin_earn_rules_chk1 CHECK (amount > 0),
    CONSTRAINT coin_earn_rules_chk2 CHECK (per_subject_limit IS NULL OR per_subject_limit > 0),
    CONSTRAINT coin_earn_rules_chk3 CHECK (lifetime_limit IS NULL OR lifetime_limit > 0)
);
COMMENT ON TABLE coin_earn_rules IS 'Configurable earning rules (amount, limits, confirmation window).';
COMMENT ON COLUMN coin_earn_rules.per_subject_limit IS 'e.g. review: 5 per product';
COMMENT ON COLUMN coin_earn_rules.lifetime_limit IS 'one-time bonuses = 1';

-- ── coin_ledger_entries (Rewards (TelCoins)) ──
CREATE TABLE coin_ledger_entries (
    id uuid NOT NULL DEFAULT uuidv7(),
    user_id uuid NOT NULL,
    entry_type ledger_entry_type NOT NULL,
    amount bigint NOT NULL,
    status ledger_status NOT NULL,
    rule_code text,
    subject_type text,
    subject_id uuid,
    reference_type text,
    reference_id uuid,
    reverses_entry_id uuid,
    fraud_hold_id uuid,
    idempotency_key text NOT NULL,
    confirmable_at timestamptz,
    status_changed_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT coin_ledger_entries_pkey PRIMARY KEY (id),
    CONSTRAINT coin_ledger_entries_idempotency_key_key UNIQUE (idempotency_key),
    CONSTRAINT coin_ledger_entries_chk1 CHECK (amount <> 0),
    CONSTRAINT coin_ledger_entries_chk2 CHECK (entry_type NOT IN ('earn','level_bonus','refund') OR amount > 0),
    CONSTRAINT coin_ledger_entries_chk3 CHECK (entry_type NOT IN ('spend','clawback') OR amount < 0),
    CONSTRAINT coin_ledger_entries_chk4 CHECK (entry_type NOT IN ('spend','clawback','refund','adjustment') OR status = 'confirmed'),
    CONSTRAINT coin_ledger_entries_chk5 CHECK (entry_type NOT IN ('clawback','refund') OR reverses_entry_id IS NOT NULL),
    CONSTRAINT coin_ledger_entries_chk6 CHECK (entry_type NOT IN ('earn') OR rule_code IS NOT NULL),
    CONSTRAINT coin_ledger_entries_chk7 CHECK (status <> 'pending' OR confirmable_at IS NOT NULL)
);
COMMENT ON TABLE coin_ledger_entries IS 'Append-only TelCoin ledger. Only status moves (pending→confirmed|frozen|reversed, frozen→confirmed|reversed). Writes go through coin_* functions.';
COMMENT ON COLUMN coin_ledger_entries.amount IS '+ earn/bonus/refund · − spend/clawback · ± adjustment';
COMMENT ON COLUMN coin_ledger_entries.subject_type IS 'product | review | media_asset | hazard_flag | referral | redemption';
COMMENT ON COLUMN coin_ledger_entries.subject_id IS 'per-subject limit key (e.g. product for reviews)';

-- ── coin_balances (Rewards (TelCoins)) ──
CREATE TABLE coin_balances (
    user_id uuid NOT NULL,
    confirmed_balance bigint NOT NULL DEFAULT 0,
    pending_balance bigint NOT NULL DEFAULT 0,
    frozen_balance bigint NOT NULL DEFAULT 0,
    lifetime_earned bigint NOT NULL DEFAULT 0,
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT coin_balances_pkey PRIMARY KEY (user_id),
    CONSTRAINT coin_balances_chk1 CHECK (pending_balance >= 0),
    CONSTRAINT coin_balances_chk2 CHECK (frozen_balance >= 0),
    CONSTRAINT coin_balances_chk3 CHECK (lifetime_earned >= 0)
);
COMMENT ON TABLE coin_balances IS 'Per-user balances maintained by coin_* functions in the same transaction; row lock serialises earn/spend. Rebuildable from the ledger.';
COMMENT ON COLUMN coin_balances.confirmed_balance IS 'may be negative after clawback (debt)';
COMMENT ON COLUMN coin_balances.lifetime_earned IS 'drives reward level';

-- ── reward_levels (Rewards (TelCoins)) ──
CREATE TABLE reward_levels (
    level smallint NOT NULL,
    title text NOT NULL,
    min_lifetime_coins bigint NOT NULL,
    earn_bonus_pct numeric(4,1) NOT NULL DEFAULT 0,
    perks jsonb NOT NULL DEFAULT '[]',
    CONSTRAINT reward_levels_pkey PRIMARY KEY (level),
    CONSTRAINT reward_levels_title_key UNIQUE (title),
    CONSTRAINT reward_levels_min_lifetime_coins_key UNIQUE (min_lifetime_coins),
    CONSTRAINT reward_levels_chk1 CHECK (level > 0),
    CONSTRAINT reward_levels_chk2 CHECK (min_lifetime_coins >= 0),
    CONSTRAINT reward_levels_chk3 CHECK (earn_bonus_pct BETWEEN 0 AND 100)
);
COMMENT ON TABLE reward_levels IS 'Level ladder (Novice → Master) by LIFETIME coins earned; a user''s level is derived, never stored.';

-- ── redemption_items (Rewards (TelCoins)) ──
CREATE TABLE redemption_items (
    code text NOT NULL,
    name text NOT NULL,
    cost_coins bigint NOT NULL,
    fulfilment_type fulfilment_type NOT NULL,
    duration interval,
    quantity integer,
    is_active boolean NOT NULL DEFAULT true,
    CONSTRAINT redemption_items_pkey PRIMARY KEY (code),
    CONSTRAINT redemption_items_chk1 CHECK (cost_coins > 0),
    CONSTRAINT redemption_items_chk2 CHECK (quantity IS NULL OR quantity > 0)
);
COMMENT ON TABLE redemption_items IS 'Catalogue of what coins buy.';

-- ── redemptions (Rewards (TelCoins)) ──
CREATE TABLE redemptions (
    id uuid NOT NULL DEFAULT uuidv7(),
    user_id uuid NOT NULL,
    item_code text NOT NULL,
    ledger_entry_id uuid NOT NULL,
    product_id uuid,
    status redemption_status NOT NULL DEFAULT 'processing',
    fulfilment jsonb,
    fulfilled_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT redemptions_pkey PRIMARY KEY (id),
    CONSTRAINT redemptions_ledger_entry_id_key UNIQUE (ledger_entry_id),
    CONSTRAINT redemptions_chk1 CHECK ((status = 'fulfilled') = (fulfilled_at IS NOT NULL))
);
COMMENT ON TABLE redemptions IS 'A redemption; its spend is exactly one ledger entry. Fulfilment evidence recorded.';

-- ── user_entitlements (Rewards (TelCoins)) ──
CREATE TABLE user_entitlements (
    id uuid NOT NULL DEFAULT uuidv7(),
    user_id uuid NOT NULL,
    source entitlement_source NOT NULL,
    redemption_id uuid,
    entitlement text NOT NULL,
    quantity integer,
    starts_at timestamptz NOT NULL DEFAULT now(),
    ends_at timestamptz,
    CONSTRAINT user_entitlements_pkey PRIMARY KEY (id),
    CONSTRAINT user_entitlements_chk1 CHECK ((source = 'redemption') = (redemption_id IS NOT NULL)),
    CONSTRAINT user_entitlements_chk2 CHECK (ends_at IS NULL OR ends_at > starts_at)
);
COMMENT ON TABLE user_entitlements IS 'Time-boxed rights from redemptions, level perks or admins (rate boost, feature access, watchlist slots).';
COMMENT ON COLUMN user_entitlements.entitlement IS 'rate_limit_x3 | feature:<flag> | watchlist_slots';

-- ── fraud_holds (Rewards (TelCoins)) ──
CREATE TABLE fraud_holds (
    id uuid NOT NULL DEFAULT uuidv7(),
    user_id uuid NOT NULL,
    reason text NOT NULL,
    rule_triggered text,
    status hold_status NOT NULL DEFAULT 'open',
    resolved_by_user_id uuid,
    resolved_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT fraud_holds_pkey PRIMARY KEY (id),
    CONSTRAINT fraud_holds_chk1 CHECK ((status = 'open') = (resolved_at IS NULL))
);
COMMENT ON TABLE fraud_holds IS 'Automatic or manual freeze of a user''s earning pending review.';

-- ── referrals (Rewards (TelCoins)) ──
CREATE TABLE referrals (
    id uuid NOT NULL DEFAULT uuidv7(),
    referrer_user_id uuid NOT NULL,
    referred_user_id uuid NOT NULL,
    status referral_status NOT NULL DEFAULT 'pending',
    qualified_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT referrals_pkey PRIMARY KEY (id),
    CONSTRAINT referrals_referred_user_id_key UNIQUE (referred_user_id),
    CONSTRAINT referrals_chk1 CHECK (referrer_user_id <> referred_user_id)
);
COMMENT ON TABLE referrals IS 'Referrer ↔ referred user; rewarded once the friend reaches Level 1. The single source of ''who referred whom''.';

-- ── user_daily_logins (Rewards (TelCoins)) ──
CREATE TABLE user_daily_logins (
    user_id uuid NOT NULL,
    login_date date NOT NULL,
    CONSTRAINT user_daily_logins_pkey PRIMARY KEY (user_id, login_date)
);
COMMENT ON TABLE user_daily_logins IS 'One row per user per active day (user''s time zone); streak length derived.';

-- ── badges (Rewards (TelCoins)) ──
CREATE TABLE badges (
    code text NOT NULL,
    name text NOT NULL,
    description text,
    CONSTRAINT badges_pkey PRIMARY KEY (code)
);
COMMENT ON TABLE badges IS 'Badge catalogue (Inspector…Master, beta tester, verified identity).';

-- ── user_badges (Rewards (TelCoins)) ──
CREATE TABLE user_badges (
    user_id uuid NOT NULL,
    badge_code text NOT NULL,
    awarded_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT user_badges_pkey PRIMARY KEY (user_id, badge_code)
);
COMMENT ON TABLE user_badges IS 'Badges awarded to users.';

-- ── posts (Community & Reviews) ──
CREATE TABLE posts (
    id uuid NOT NULL DEFAULT uuidv7(),
    author_user_id uuid NOT NULL,
    product_id uuid NOT NULL,
    wallet_item_id uuid,
    body text NOT NULL,
    geohash text,
    location_name text,
    country_code char(2),
    status content_status NOT NULL DEFAULT 'published',
    comment_count integer NOT NULL DEFAULT 0,
    reaction_count integer NOT NULL DEFAULT 0,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    deleted_at timestamptz,
    CONSTRAINT posts_pkey PRIMARY KEY (id),
    CONSTRAINT posts_chk1 CHECK (geohash IS NULL OR geohash ~ '^[0-9b-hjkmnp-z]{6}$'),
    CONSTRAINT posts_chk2 CHECK (comment_count >= 0),
    CONSTRAINT posts_chk3 CHECK (reaction_count >= 0)
);
COMMENT ON TABLE posts IS 'Community post about a product. Location stored only as a ~1 km geohash cell (privacy).';
COMMENT ON COLUMN posts.geohash IS 'precision 6 ≈ 1.2 km';
COMMENT ON COLUMN posts.deleted_at IS 'soft delete';

-- ── post_media (Community & Reviews) ──
CREATE TABLE post_media (
    post_id uuid NOT NULL,
    media_asset_id uuid NOT NULL,
    sort_order smallint NOT NULL DEFAULT 0,
    CONSTRAINT post_media_pkey PRIMARY KEY (post_id, media_asset_id)
);
COMMENT ON TABLE post_media IS 'Photos/videos attached to a post.';

-- ── comments (Community & Reviews) ──
CREATE TABLE comments (
    id uuid NOT NULL DEFAULT uuidv7(),
    post_id uuid,
    risk_event_id uuid,
    author_user_id uuid NOT NULL,
    parent_comment_id uuid,
    body text NOT NULL,
    status content_status NOT NULL DEFAULT 'published',
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    deleted_at timestamptz,
    CONSTRAINT comments_pkey PRIMARY KEY (id),
    CONSTRAINT comments_chk1 CHECK (num_nonnulls(post_id, risk_event_id) = 1),
    CONSTRAINT comments_chk2 CHECK (parent_comment_id IS NULL OR parent_comment_id <> id)
);
COMMENT ON TABLE comments IS 'Threaded discussion on a post or on a risk event (Risk Timeline community thread).';
COMMENT ON COLUMN comments.deleted_at IS 'soft delete';

-- ── reactions (Community & Reviews) ──
CREATE TABLE reactions (
    post_id uuid NOT NULL,
    user_id uuid NOT NULL,
    reaction reaction_type NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT reactions_pkey PRIMARY KEY (post_id, user_id)
);
COMMENT ON TABLE reactions IS 'One reaction per user per post.';

-- ── hazard_flags (Community & Reviews) ──
CREATE TABLE hazard_flags (
    id uuid NOT NULL DEFAULT uuidv7(),
    reporter_user_id uuid NOT NULL,
    product_id uuid NOT NULL,
    wallet_item_id uuid,
    dimension_code text,
    description text,
    geohash text,
    status flag_status NOT NULL DEFAULT 'pending',
    matched_recall_id uuid,
    reviewed_by_user_id uuid,
    reviewed_at timestamptz,
    resolution_note text,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT hazard_flags_pkey PRIMARY KEY (id),
    CONSTRAINT hazard_flags_chk1 CHECK (geohash IS NULL OR geohash ~ '^[0-9b-hjkmnp-z]{6}$'),
    CONSTRAINT hazard_flags_chk2 CHECK ((status = 'pending') = (reviewed_at IS NULL)),
    CONSTRAINT hazard_flags_chk3 CHECK (status <> 'confirmed' OR matched_recall_id IS NOT NULL OR reviewed_by_user_id IS NOT NULL)
);
COMMENT ON TABLE hazard_flags IS 'User-reported suspected hazard; coins only once confirmed (recall match or moderator).';
COMMENT ON COLUMN hazard_flags.dimension_code IS 'hazard type';

-- ── hazard_flag_media (Community & Reviews) ──
CREATE TABLE hazard_flag_media (
    hazard_flag_id uuid NOT NULL,
    media_asset_id uuid NOT NULL,
    CONSTRAINT hazard_flag_media_pkey PRIMARY KEY (hazard_flag_id, media_asset_id)
);
COMMENT ON TABLE hazard_flag_media IS 'Evidence photos on a hazard flag.';

-- ── product_fact_reports (Community & Reviews) ──
CREATE TABLE product_fact_reports (
    id uuid NOT NULL DEFAULT uuidv7(),
    product_id uuid NOT NULL,
    reporter_user_id uuid NOT NULL,
    hazard_flag_id uuid,
    attribute text NOT NULL,
    current_value text,
    proposed_value text,
    is_confirmation boolean NOT NULL,
    status fact_report_status NOT NULL DEFAULT 'pending',
    reviewed_by_user_id uuid,
    reviewed_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT product_fact_reports_pkey PRIMARY KEY (id),
    CONSTRAINT product_fact_reports_chk1 CHECK (is_confirmation OR proposed_value IS NOT NULL),
    CONSTRAINT product_fact_reports_chk2 CHECK ((status = 'pending') = (reviewed_at IS NULL))
);
COMMENT ON TABLE product_fact_reports IS 'User confirms or corrects a flagged product fact; accepted reports earn coins.';
COMMENT ON COLUMN product_fact_reports.hazard_flag_id IS 'flag being verified, if any';

-- ── topics (Commerce Feed & Personalisation) ──
CREATE TABLE topics (
    code text NOT NULL,
    name text NOT NULL,
    sort_order smallint NOT NULL DEFAULT 0,
    CONSTRAINT topics_pkey PRIMARY KEY (code)
);
COMMENT ON TABLE topics IS 'Attribute/topic filter values.';

-- ── feed_items (Commerce Feed & Personalisation) ──
CREATE TABLE feed_items (
    id uuid NOT NULL DEFAULT uuidv7(),
    item_type feed_item_type NOT NULL,
    data_source_code text NOT NULL,
    external_id text,
    source_record_id uuid,
    media_asset_id uuid,
    post_id uuid,
    recall_id uuid,
    product_id uuid,
    category_id uuid,
    country_code char(2),
    title text,
    ai_label text,
    ai_confidence numeric(4,3),
    trending_score real NOT NULL DEFAULT 0,
    is_public boolean NOT NULL DEFAULT true,
    published_at timestamptz NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT feed_items_pkey PRIMARY KEY (id),
    CONSTRAINT feed_items_chk1 CHECK (item_type <> 'user_upload' OR media_asset_id IS NOT NULL),
    CONSTRAINT feed_items_chk2 CHECK (item_type NOT IN ('listing','social_post') OR (external_id IS NOT NULL AND source_record_id IS NOT NULL)),
    CONSTRAINT feed_items_chk3 CHECK (item_type <> 'recall' OR recall_id IS NOT NULL),
    CONSTRAINT feed_items_chk4 CHECK (item_type <> 'community_post' OR post_id IS NOT NULL),
    CONSTRAINT feed_items_chk5 CHECK (ai_confidence BETWEEN 0 AND 1)
);
COMMENT ON TABLE feed_items IS 'A card in For You / Explore, keyed on its origin so re-ingestion updates rather than duplicates.';
COMMENT ON COLUMN feed_items.trending_score IS 'not indexed (keeps HOT updates)';

-- ── feed_item_topics (Commerce Feed & Personalisation) ──
CREATE TABLE feed_item_topics (
    feed_item_id uuid NOT NULL,
    topic_code text NOT NULL,
    confidence numeric(4,3),
    CONSTRAINT feed_item_topics_pkey PRIMARY KEY (feed_item_id, topic_code)
);
COMMENT ON TABLE feed_item_topics IS 'Topics tagged on a feed item (AI-assigned with confidence).';

-- ── search_queries (Commerce Feed & Personalisation) ──
CREATE TABLE search_queries (
    id uuid NOT NULL DEFAULT uuidv7(),
    user_id uuid NOT NULL,
    query_text text,
    query_media_id uuid,
    clicked_product_id uuid,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT search_queries_pkey PRIMARY KEY (id),
    CONSTRAINT search_queries_chk1 CHECK (num_nonnulls(query_text, query_media_id) >= 1)
);
COMMENT ON TABLE search_queries IS 'User search history (text or image).';

-- ── feed_interactions (Commerce Feed & Personalisation) ──
CREATE TABLE feed_interactions (
    id uuid NOT NULL DEFAULT uuidv7(),
    user_id uuid NOT NULL,
    feed_item_id uuid NOT NULL,
    action feed_action NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT feed_interactions_pkey PRIMARY KEY (id, created_at)
) PARTITION BY RANGE (created_at);
COMMENT ON TABLE feed_interactions IS 'Implicit feedback for ranking. Monthly partitions.';
COMMENT ON COLUMN feed_interactions.user_id IS 'no FK on partitioned log; purged on account deletion';

-- ── price_snapshots (Pricing) ──
CREATE TABLE price_snapshots (
    id uuid NOT NULL DEFAULT uuidv7(),
    product_id uuid NOT NULL,
    data_source_code text NOT NULL,
    seller_name text,
    listing_url text,
    country_code char(2) NOT NULL,
    currency char(3) NOT NULL,
    price numeric(12,2) NOT NULL,
    in_stock boolean,
    observed_at timestamptz NOT NULL,
    CONSTRAINT price_snapshots_pkey PRIMARY KEY (id),
    CONSTRAINT price_snapshots_chk1 CHECK (price >= 0),
    CONSTRAINT price_snapshots_chk2 CHECK (currency ~ '^[A-Z]{3}$')
);
COMMENT ON TABLE price_snapshots IS 'Observed prices per product, source, seller and currency over time.';

-- ── price_alerts (Pricing) ──
CREATE TABLE price_alerts (
    id uuid NOT NULL DEFAULT uuidv7(),
    wallet_item_id uuid NOT NULL,
    target_price numeric(12,2) NOT NULL,
    currency char(3) NOT NULL,
    status price_alert_status NOT NULL DEFAULT 'active',
    last_triggered_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT price_alerts_pkey PRIMARY KEY (id),
    CONSTRAINT price_alerts_chk1 CHECK (target_price > 0),
    CONSTRAINT price_alerts_chk2 CHECK (currency ~ '^[A-Z]{3}$')
);
COMMENT ON TABLE price_alerts IS 'Target-price alert on a wallet product (owner = wallet item''s user).';

-- ── risk_events (Risk Events & Notifications) ──
CREATE TABLE risk_events (
    id uuid NOT NULL DEFAULT uuidv7(),
    product_id uuid NOT NULL,
    event_type risk_event_type NOT NULL,
    severity severity NOT NULL,
    screening_id uuid,
    recall_id uuid,
    certification_check_id uuid,
    hazard_assessment_id uuid,
    price_snapshot_id uuid,
    hazard_flag_id uuid,
    title text NOT NULL,
    summary text,
    detected_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT risk_events_pkey PRIMARY KEY (id),
    CONSTRAINT risk_events_chk1 CHECK (CASE event_type WHEN 'recall_match' THEN recall_id IS NOT NULL AND screening_id IS NOT NULL WHEN 'recall_near_match' THEN recall_id IS NOT NULL AND screening_id IS NOT NULL WHEN 'hazard_threshold' THEN hazard_assessment_id IS NOT NULL WHEN 'certification_change' THEN certification_check_id IS NOT NULL WHEN 'price_drop' THEN price_snapshot_id IS NOT NULL WHEN 'community_flag_confirmed' THEN hazard_flag_id IS NOT NULL END)
);
COMMENT ON TABLE risk_events IS 'A product-level risk signal, created once per (product, cause) — re-screens do not duplicate it.';

-- ── risk_event_media (Risk Events & Notifications) ──
CREATE TABLE risk_event_media (
    risk_event_id uuid NOT NULL,
    media_asset_id uuid NOT NULL,
    sort_order smallint NOT NULL DEFAULT 0,
    CONSTRAINT risk_event_media_pkey PRIMARY KEY (risk_event_id, media_asset_id)
);
COMMENT ON TABLE risk_event_media IS 'Images/videos shown in a risk instance''s detail feed.';

-- ── user_risk_alerts (Risk Events & Notifications) ──
CREATE TABLE user_risk_alerts (
    id uuid NOT NULL DEFAULT uuidv7(),
    user_id uuid NOT NULL,
    risk_event_id uuid NOT NULL,
    wallet_item_id uuid,
    price_alert_id uuid,
    status risk_alert_status NOT NULL DEFAULT 'new',
    action_taken text,
    seen_at timestamptz,
    resolved_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT user_risk_alerts_pkey PRIMARY KEY (id),
    CONSTRAINT user_risk_alerts_user_id_risk_event_id_key UNIQUE (user_id, risk_event_id),
    CONSTRAINT user_risk_alerts_chk1 CHECK (status NOT IN ('confirmed','dismissed','resolved') OR resolved_at IS NOT NULL)
);
COMMENT ON TABLE user_risk_alerts IS 'A risk instance in one user''s timeline; the user investigates then confirms or dismisses.';

-- ── notifications (Risk Events & Notifications) ──
CREATE TABLE notifications (
    id uuid NOT NULL DEFAULT uuidv7(),
    user_id uuid NOT NULL,
    channel notification_channel NOT NULL,
    template_code text NOT NULL,
    payload jsonb NOT NULL DEFAULT '{}',
    user_risk_alert_id uuid,
    status notification_status NOT NULL DEFAULT 'queued',
    error text,
    sent_at timestamptz,
    read_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT notifications_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE notifications IS 'Outbound notification per channel with delivery status.';

-- ── notification_preferences (Risk Events & Notifications) ──
CREATE TABLE notification_preferences (
    user_id uuid NOT NULL,
    channel notification_channel NOT NULL,
    category text NOT NULL,
    enabled boolean NOT NULL DEFAULT true,
    CONSTRAINT notification_preferences_pkey PRIMARY KEY (user_id, channel, category)
);
COMMENT ON TABLE notification_preferences IS 'Per-user, per-channel, per-category opt in/out.';
COMMENT ON COLUMN notification_preferences.category IS 'recall | price | community | marketing';

-- ── user_devices (Risk Events & Notifications) ──
CREATE TABLE user_devices (
    id uuid NOT NULL DEFAULT uuidv7(),
    user_id uuid NOT NULL,
    platform text NOT NULL,
    push_token text NOT NULL,
    last_seen_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT user_devices_pkey PRIMARY KEY (id),
    CONSTRAINT user_devices_push_token_key UNIQUE (push_token),
    CONSTRAINT user_devices_chk1 CHECK (platform IN ('ios','android','web'))
);
COMMENT ON TABLE user_devices IS 'Push tokens for the (future) mobile app and web push.';

-- ── feature_flags (Platform, Audit & Operations) ──
CREATE TABLE feature_flags (
    code text NOT NULL,
    description text,
    is_enabled boolean NOT NULL DEFAULT false,
    rollout jsonb NOT NULL DEFAULT '{}',
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT feature_flags_pkey PRIMARY KEY (code)
);
COMMENT ON TABLE feature_flags IS 'Feature flags / early-access gates.';

