-- ── triggers & partitions ──
CREATE TRIGGER trust_score_events_guard_immutable BEFORE UPDATE OR DELETE ON trust_score_events FOR EACH ROW EXECUTE FUNCTION telcron_guard_immutable();
CREATE TRIGGER coin_ledger_entries_guard_immutable BEFORE UPDATE OR DELETE ON coin_ledger_entries FOR EACH ROW EXECUTE FUNCTION telcron_guard_immutable('status', 'status_changed_at', 'fraud_hold_id', 'confirmable_at');
CREATE TRIGGER coin_balances_set_updated_at BEFORE UPDATE ON coin_balances FOR EACH ROW EXECUTE FUNCTION telcron_set_updated_at();
CREATE TRIGGER posts_set_updated_at BEFORE UPDATE ON posts FOR EACH ROW EXECUTE FUNCTION telcron_set_updated_at();
CREATE TRIGGER comments_set_updated_at BEFORE UPDATE ON comments FOR EACH ROW EXECUTE FUNCTION telcron_set_updated_at();
CREATE TRIGGER search_queries_guard_immutable BEFORE UPDATE OR DELETE ON search_queries FOR EACH ROW EXECUTE FUNCTION telcron_guard_immutable();
CREATE TRIGGER feed_interactions_guard_immutable BEFORE UPDATE OR DELETE ON feed_interactions FOR EACH ROW EXECUTE FUNCTION telcron_guard_immutable();
SELECT telcron_create_monthly_partitions('feed_interactions', date_trunc('month', now())::date, 4);
CREATE TRIGGER price_snapshots_guard_immutable BEFORE UPDATE OR DELETE ON price_snapshots FOR EACH ROW EXECUTE FUNCTION telcron_guard_immutable();
CREATE TRIGGER price_alerts_set_updated_at BEFORE UPDATE ON price_alerts FOR EACH ROW EXECUTE FUNCTION telcron_set_updated_at();
CREATE TRIGGER risk_events_guard_immutable BEFORE UPDATE OR DELETE ON risk_events FOR EACH ROW EXECUTE FUNCTION telcron_guard_immutable();
CREATE TRIGGER feature_flags_set_updated_at BEFORE UPDATE ON feature_flags FOR EACH ROW EXECUTE FUNCTION telcron_set_updated_at();
$phase3$;
END $migrate$;

-- migrate:down
-- Irreversible (S-18): the phase may predate this migration; dropping it would destroy data it never made.
-- Undoing it is a new, reviewed migration, never `dbmate rollback`.
DO $rollback$
BEGIN
    RAISE EXCEPTION 'irreversible: phase 3 schema (S-18); write a new migration instead of rolling back';
END $rollback$;
